//   node --test .github/prune/test/
// The newest-N rule and the generated keep-list, on fixture trees in the shape of the real indexes.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { parsePackages, selectRepo } from '../prune.mjs';
import { parseKeepList, keepEntries, missing } from '../keeplist.mjs';

const select = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'select.mjs');

const stanza = (name, ver, arch = 'amd64') => `Package: ${name}
Version: ${ver}
Architecture: ${arch}
Source: ${name}
Filename: ./${name}_${ver}_${arch}.deb
Size: 1000
`;
const debs = (name, vers) => vers.map((v) => stanza(name, v)).join('\n');
const pkgs = (text) => parsePackages(text, 'debian/bookworm');
const verdict = (r) => ({ keep: r.keep.map((p) => p.version).sort(), delete: r.delete.map((p) => p.version).sort() });

function keepList(lines) {
  const body = lines.map((l) => l.join('\t'));
  const sum = crypto.createHash('sha256').update(body.join('\n') + '\n').digest('hex');
  return ['# GENERATED by channel/gen-keep-list.mjs from the pins named below.', ...body, `# sum ${sum}`, ''].join('\n');
}

test('newest 3: the 4th and older builds of an unpinned package go', () => {
  const r = selectRepo(pkgs(debs('foo', ['1.0-1', '1.1-1', '1.2-1', '1.3-1', '1.4-1'])), [], { newest: 3 });
  assert.deepEqual(verdict(r), { keep: ['1.2-1', '1.3-1', '1.4-1'], delete: ['1.0-1', '1.1-1'] });
});

test('newest 3: a pinned old version survives beside the three newest', () => {
  const lines = parseKeepList(keepList([['foo', '1.0-1', 'debian/bookworm/*', 'zynthian-sys@omx-track/x:install.sh']]));
  const r = selectRepo(pkgs(debs('foo', ['1.0-1', '1.1-1', '1.2-1', '1.3-1', '1.4-1'])), keepEntries(lines), { newest: 3 });
  assert.deepEqual(verdict(r), { keep: ['1.0-1', '1.2-1', '1.3-1', '1.4-1'], delete: ['1.1-1'] });
});

test('newest 1 (the default) is the old behaviour', () => {
  const r = selectRepo(pkgs(debs('foo', ['1.0-1', '1.1-1', '1.2-1'])), []);
  assert.deepEqual(verdict(r), { keep: ['1.2-1'], delete: ['1.0-1', '1.1-1'] });
});

test('a pin of another distro does not keep a build here', () => {
  const lines = parseKeepList(keepList([['foo', '1.0-1', 'fedora/44/*', 'platform:baked']]));
  const r = selectRepo(pkgs(debs('foo', ['1.0-1', '1.1-1', '1.2-1', '1.3-1', '1.4-1'])), keepEntries(lines), { newest: 3 });
  assert.ok(r.delete.some((p) => p.version === '1.0-1'));
});

test('newest 3 counts builds per architecture', () => {
  const text = [stanza('foo', '1.0-1', 'amd64'), stanza('foo', '1.1-1', 'amd64'), stanza('foo', '1.2-1', 'amd64'), stanza('foo', '1.3-1', 'amd64'),
    stanza('foo', '1.0-1', 'arm64'), stanza('foo', '1.1-1', 'arm64')].join('\n');
  const r = selectRepo(pkgs(text), [], { newest: 3 });
  assert.deepEqual(r.delete.map((p) => `${p.version} ${p.arch}`), ['1.0-1 amd64']);
});

test('keep-list: a hand-added line, a hand edit and a missing header are refused', () => {
  const good = keepList([['foo', '1.0-1', 'debian/bookworm/*', 'a:b']]);
  assert.equal(parseKeepList(good).length, 1);
  assert.throws(() => parseKeepList(good.replace('# sum', 'foo\t9.9-9\tdebian/bookworm/*\thand\n# sum')), /sum/);
  assert.throws(() => parseKeepList(good.replace('1.0-1', '1.0-2')), /sum/);
  assert.throws(() => parseKeepList(good.replace('# GENERATED', '# written')), /GENERATED/);
  assert.throws(() => parseKeepList(good.replace('\ta:b', '\t')), /not "package/);
});

test('keep-list: a pin the channel does not serve is named (missing pin)', () => {
  const lines = parseKeepList(keepList([
    ['foo', '1.0-1', 'debian/bookworm/*', 'p1'], ['foo', '9.9-1', 'debian/bookworm/*', 'p2'],
    ['foo', '>=2.0', 'debian/bookworm/*', 'p3'], ['foo', '>=1.2', 'debian/bookworm/*', 'p4'],
    ['gone', 'newest', 'debian/bookworm/amd64', 'p5'], ['foo', 'newest', 'debian/trixie/*', 'p6'],
  ]));
  const m = missing(lines, pkgs(debs('foo', ['1.0-1', '1.2-1'])));
  assert.deepEqual(m.map((x) => x.split(':')[0]), ['foo 9.9-1 debian/bookworm/*', 'foo >=2.0 debian/bookworm/*', 'gone newest debian/bookworm/amd64', 'foo newest debian/trixie/*']);
});

test('cli: select.mjs exits 1 on a missing pin and on a tampered keep-list; --newest 3 prints sizes', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'keeplist-'));
  const suite = path.join(dir, 'deb/debian/bookworm');
  fs.mkdirSync(suite, { recursive: true });
  fs.writeFileSync(path.join(suite, 'Packages'), debs('foo', ['1.0-1', '1.1-1', '1.2-1', '1.3-1', '1.4-1']));
  fs.writeFileSync(path.join(dir, 'keep.yml'), 'keep:\n');
  const run = (kl, extra = []) => {
    fs.writeFileSync(path.join(dir, 'kl.txt'), kl);
    return spawnSync('node', [select, '--keep', path.join(dir, 'keep.yml'), '--keeplist', path.join(dir, 'kl.txt'), '--tree', dir, '--newest', '3', ...extra], { encoding: 'utf8' });
  };
  const ok = run(keepList([['foo', '1.0-1', 'debian/bookworm/*', 'p1']]));
  assert.equal(ok.status, 0, ok.stderr);
  assert.match(ok.stdout, /deb: keep 4 \(0\.0 MiB\), delete 1 \(0\.0 MiB\)/);
  const gone = run(keepList([['foo', '7.7-1', 'debian/bookworm/*', 'p1']]));
  assert.equal(gone.status, 1);
  assert.match(gone.stderr, /does not serve[\s\S]*foo 7\.7-1/);
  const bad = run(keepList([['foo', '1.0-1', 'debian/bookworm/*', 'p1']]).replace('1.0-1', '1.1-1'));
  assert.notEqual(bad.status, 0);
  assert.match(bad.stderr, /sum/);
  fs.rmSync(dir, { recursive: true });
});

test('a pinned build names its release: the other builds of that version are not the pin', () => {
  const lines = parseKeepList(keepList([['foo', '1.0-2', 'debian/bookworm/*', 'p']]));
  const r = selectRepo(pkgs(debs('foo', ['1.0-1', '1.0-2', '1.1-1', '1.2-1', '1.3-1', '1.4-1'])), keepEntries(lines), { newest: 3 });
  assert.deepEqual(verdict(r).keep, ['1.0-2', '1.2-1', '1.3-1', '1.4-1']);
  assert.ok(r.delete.some((p) => p.version === '1.0-1'));
  assert.ok(missing(lines, pkgs(debs('foo', ['1.0-1']))).length === 1, 'a release the channel lacks is a missing pin');
});
